def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_last = history[-1][1]

    opp_c = 0
    trans_cd = 0
    trans_dc = 0
    trans_dd = 0

    for i in range(n):
        me, opp = history[i]
        if opp == 'C':
            opp_c += 1
        if i > 0:
            prev_me = history[i - 1][0]
            if prev_me == 'C' and opp == 'D':
                trans_cd += 1
            elif prev_me == 'D' and opp == 'C':
                trans_dc += 1
            elif prev_me == 'D' and opp == 'D':
                trans_dd += 1

    rate = opp_c / n

    w = min(10, n)
    start = n - w
    recent_c = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_c += 1

    streak = 0
    if opp_last == 'D':
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                streak += 1
            else:
                break

    if rate <= 0.25:
        if opp_last == 'C' and recent_c >= 6:
            return 'C'
        return 'D'

    if opp_last == 'D' and streak >= 8 and recent_c <= 2:
        return 'D'

    if opp_last == 'C':
        if n >= 90 and trans_dc >= 4 and trans_dc >= trans_dd and recent_c >= 6:
            return 'D'
        return 'C'

    if n >= 2 and history[-2][0] == 'D':
        if streak == 1:
            if rate >= 0.35 or recent_c >= 3:
                return 'C'
            return 'D'
        if streak == 2:
            if rate >= 0.70 and recent_c >= 5:
                return 'C'
            return 'D'
        if streak <= 4:
            if rate >= 0.90 and recent_c >= 5 and trans_dc >= trans_dd:
                return 'C'
            return 'D'
        return 'D'

    if streak == 1:
        if rate >= 0.90 and trans_cd <= 1 and recent_c >= 8:
            return 'C'
        if rate >= 0.80 and trans_cd <= 2 and recent_c >= 8 and trans_dc >= trans_dd:
            return 'C'
        if trans_dd > trans_dc and rate >= 0.65 and recent_c >= 5:
            return 'C'
        return 'D'

    return 'D'
